export interface LegacyFlowContextMigrationItem {flowId:string;occurrenceId:string;flowName:string;occurrenceName:string;pageName:string;eventName:string;trigger:string}
export interface LegacyFlowContextMigrationBlocker {flowId:string;occurrenceId:string;flowName:string;occurrenceName:string;message:string}
export interface LegacyFlowContextMigrationReview {items:LegacyFlowContextMigrationItem[];blockers:LegacyFlowContextMigrationBlocker[]}
export function reviewLegacyFlowContextMigration(project:SpecificationProject,flowId:string):LegacyFlowContextMigrationReview{void flowId;const items:LegacyFlowContextMigrationItem[]=[],blockers:LegacyFlowContextMigrationBlocker[]=[];for(const[candidateFlowId,graph]of Object.entries(graphIndex(project))){const flow=project.collections.flows.find(({id})=>id===candidateFlowId),flowName=flow?.name??"Unknown Flow";for(const occurrence of graph.occurrences){if(!legacyBindingOccurrence(occurrence))continue;const occurrenceName=typeof occurrence.name==="string"&&occurrence.name.trim()?occurrence.name.trim():"Unnamed occurrence",base={flowId:candidateFlowId,occurrenceId:occurrence.id,flowName,occurrenceName},page=project.collections.pages.find(({id})=>id===occurrence.pageId);if(!page){blockers.push({...base,message:`${occurrenceName} in ${flowName} has a missing Page.`});continue;}const binding=((page.contextEventBindings as ProjectEntity[]|undefined)??[]).find(({id})=>id===occurrence.contextBindingId);if(!binding){blockers.push({...base,message:`${occurrenceName} in ${flowName} has a missing Page binding on ${page.name}.`});continue;}const event=project.collections.events.find(({id})=>id===binding.eventId);if(!event){blockers.push({...base,message:`${occurrenceName} in ${flowName} has a missing Event on ${page.name}.`});continue;}items.push({...base,pageName:page.name,eventName:event.name,trigger:String(binding.trigger??binding.name??"")});}}return{items,blockers};}
export function migrateLegacyFlowContextBindings(state:ProjectState,flowId:string):ProjectState{const review=reviewLegacyFlowContextMigration(state.project,flowId);if(review.blockers.length||!review.items.length)return state;return transactProject(state,"Migrate legacy Flow Page context bindings",(project)=>{const eventsById=new Map(project.collections.events.map((event)=>[event.id,event])),primaryBindingByPage=new Map<string,string>(),pages=project.collections.pages.map((page)=>{const bindings=(page.contextEventBindings as ProjectEntity[]|undefined)??[],primary=bindings[0];if(primary)primaryBindingByPage.set(page.id,primary.id);const{contextEventBindings,eventName,pathname,...stored}=page;void contextEventBindings;void eventName;void pathname;return stored as ProjectEntity;}),pagesById=new Map(project.collections.pages.map((page)=>[page.id,page])),documentationFlowGraphs=Object.fromEntries(Object.entries(graphIndex(project)).map(([candidateFlowId,graph])=>{const occurrenceFrameIds=new Map(graph.occurrences.flatMap((occurrence)=>typeof occurrence.pageFrameId==="string"?[[occurrence.id,occurrence.pageFrameId] as const]:[])),removed=new Set(graph.occurrences.filter((occurrence)=>legacyBindingOccurrence(occurrence)&&primaryBindingByPage.get(String(occurrence.pageId))===occurrence.contextBindingId).map(({id})=>id)),occurrences=graph.occurrences.flatMap((occurrence)=>{const{role:discardedRole,...roleFree}=occurrence;void discardedRole;if(removed.has(occurrence.id))return[];if(!legacyBindingOccurrence(occurrence))return[roleFree];const page=pagesById.get(String(occurrence.pageId)),binding=((page?.contextEventBindings as ProjectEntity[]|undefined)??[]).find(({id})=>id===occurrence.contextBindingId),event=eventsById.get(String(binding?.eventId??""));if(!binding||!event)return[roleFree];const{contextBindingId,eventId:discardedEventId,trigger:discardedTrigger,...stored}=roleFree;void contextBindingId;void discardedEventId;void discardedTrigger;return[{...stored,eventId:event.id,trigger:String(binding.trigger??binding.name??"")}];}),migrateEndpoint=(endpoint:StoredFlowEndpointReference|undefined):StoredFlowEndpointReference|undefined=>endpoint?.kind==="event-occurrence"&&occurrenceFrameIds.has(endpoint.id)?{kind:"page-frame",id:occurrenceFrameIds.get(endpoint.id)!}:endpoint,relationships=graph.relationships.map((relationship)=>{const sourceEndpoint=migrateEndpoint(relationshipEndpoint(relationship,"source")),targetEndpoint=migrateEndpoint(relationshipEndpoint(relationship,"target"));if(!sourceEndpoint||!targetEndpoint)return relationship;const{sourceNodeId:discardedSource,targetNodeId:discardedTarget,...stored}=relationship;void discardedSource;void discardedTarget;return{...stored,sourceEndpoint,targetEndpoint};});return[candidateFlowId,{...graph,occurrences,relationships}];})),events=project.collections.events.map((event)=>{const{role,...stored}=event;void role;return stored as ProjectEntity;});return{...project,collections:{...project.collections,pages,events},documentationFlowGraphs};});}
export function migrateLegacyFlowRelationshipKinds(state:ProjectState,flowId:string):ProjectState{const graph=storedGraph(state.project,flowId);if(!graph.relationships.some((relationship)=>relationship.kind==="parallel"))return state;return transactProject(state,"Migrate legacy Flow relationship kinds",(project)=>{const current=storedGraph(project,flowId);return saveStoredGraph(project,flowId,{...current,relationships:current.relationships.map((relationship)=>relationship.kind==="parallel"?{...relationship,...relationshipPorts(relationship),kind:"alternative"}:relationship)});});}
